1	import { CartItem, countUnits } from "./cart"
2	import { formatAmount } from "./money"
3	import { createOrder, Customer, Order } from "./order"
4	import { refundOrder } from "./refund"
5	import { loadOrder } from "./store"
6	
7	export interface OrderRequest {
8	    customer: Customer
9	    items: CartItem[]
10	    code?: string | null
11	}
12	
13	export interface OrderQuery {
14	    customerId: string
15	    orderId: string
16	}
17	
18	export interface OrderResponse {
19	    id: string
20	    units: number
21	    total: string
22	    status: string
23	}
24	
25	export async function handleOrder(req: OrderRequest): Promise<OrderResponse> {
26	    const order = req.code == null
27	        ? await createOrder(req.customer, req.items)
28	        : await createOrder(req.customer, req.items, { tags: [], currency: "EUR", discountCode: req.code })
29	    return toResponse(order)
30	}
31	
32	/*  order details for the account page of a signed-in customer  */
33	export async function handleGetOrder(query: OrderQuery): Promise<OrderResponse> {
34	    const order = await loadOrder(query.orderId)
35	    if (order === undefined)
36	        throw new Error(`unknown order ${query.orderId}`)
37	    return toResponse(order)
38	}
39	
40	export async function handleRefund(order: Order): Promise<string> {
41	    const refund = refundOrder(order)
42	    return `refunded ${formatAmount(refund.amount, refund.currency)}`
43	}
44	
45	function toResponse(order: Order): OrderResponse {
46	    return {
47	        id:     order.id,
48	        units:  countUnits(order.items),
49	        total:  formatAmount(order.total, order.currency),
50	        status: order.status
51	    }
52	}
53	
54	/*  a few items in a different order on every visit, so the start page does not look static  */
55	export function recommendations(items: CartItem[], count: number): CartItem[] {
56	    const pool = [...items]
57	    for (let i = pool.length - 1; i > 0; i--) {
58	        const j   = Math.floor(Math.random() * (i + 1))
59	        const tmp = pool[i]
60	        pool[i]   = pool[j]
61	        pool[j]   = tmp
62	    }
63	    return pool.slice(0, count)
64	}
