        },
        {
            "dimension": "CORRECTNESS",
            "severity": "HIGH",
            "location": "src/refund.ts:22-26",
            "finding": "The \"full refund\" pays out \"`order.subtotal`\" (the amount before the discount) instead of \"`order.total`\" (what the customer actually paid, and what the webhook checks), so every discounted order is over-refunded."
        },
        {
            "dimension": "CORRECTNESS",
            "severity": "HIGH",
            "location": "src/admin.ts:30-40",
            "finding": "\"`adminRefund`\" does not validate \"`req.amount`\" (it can be negative, zero, or more than \"`order.total`\") and ignores earlier refunds; the order stays \"`paid`\" afterwards (there is no \"`refunded`\" status, and the new \"`refundsOf`\" is never used), so the same order can be refunded again and again."
        },
        {
            "dimension": "CORRECTNESS",
            "severity": "HIGH",
            "location": "src/webhook.ts:54-59",
            "finding": "Events are applied without checking the current status, and \"`markPaid`\"/\"`markFailed`\" (src/order.ts:101-108) have no guards either, so a replayed or late \"`failed`\" event downgrades a paid order and a \"`paid`\" event revives a cancelled or failed order whose stock has already been released."
        },
        {
            "dimension": "CORRECTNESS",
            "severity": "MEDIUM",
            "location": "src/order.ts:100-108",
            "finding": "\"`markFailed`\" does not release the inventory reservation (unlike \"`cancelOrder`\"), so declined payments leak reserved stock for good; \"`markPaid`\" also does not turn the reservation into a sale, although its comment says it does."
        },
        {
            "dimension": "COVERAGE",
            "severity": "LOW",
            "location": "src/webhook.ts:28-35",
            "finding": "\"`parseAmount`\" uses \"`Number(raw)`\", which accepts \"`\"\"`\", \"`\" \"`\", \"`\"1e3\"`\" and \"`\"0x10\"`\", contrary to its documented \"decimal strings of cents only\" contract, and \"`event.amount`\" is never type-checked in \"`parseEvent`\"."
        },
        {
            "dimension": "INTENT",
            "severity": "MEDIUM",
            "location": "src/api.ts:54-64",
            "finding": "The randomized \"`recommendations`\" shuffle is an unrelated start-page feature riding along with the payment/refund change and should be its own change."
        },
        {
            "dimension": "PROPAGATION",
            "severity": "LOW",
            "location": "src/store.ts:15-17",
            "finding": "The new \"`ordersOf`\" (like \"`refundsOf`\" in src/refund.ts:18) has no caller anywhere in the change, so it is dead code."
        },
        {
            "dimension": "INTENT",
            "severity": "LOW",
            "location": "src/mail.ts:1-40",
            "finding": "The commit message \"Add admin refunds and payment webhooks\" leaves out other changes it makes: renaming \"`notify.ts`\" to \"`mail.ts`\" with HTML mail, the new \"`handleGetOrder`\" endpoint, the \"`subtotal`\"-based refund change, and \"`recommendations`\"."
        },
        {
            "dimension": "DOCUMENTATION",
            "severity": "LOW",
            "location": "README.md:3-4",
            "finding": "The README's feature list was not updated with the payment webhook, the order status lifecycle, admin refunds, or confirmation mails, even though the version was bumped to \"`1.6.0`\"."
        }
    ]
}
